import React from 'react';
import { useForm } from 'react-hook-form';
import {
  TextField,
  Button,
  MenuItem,
  InputLabel,
  Select,
  FormControl,
  Box,
  Card,
  Avatar,
  CardContent,
  Typography,
} from '@mui/material';
import { View } from '@chakra-ui/react/dist/types/components/color-picker/namespace';
import DiseaseForm from './DiseaseForm';
import { NurseFormProvider } from '../../Context/NurseFormContext';

type FormData = {
  no: number;
  create_at: string;
  employee_id: string;
  significant_characteristic: string;
  disease_group: string;
  create_by: number;
  status: string;
  disease_group_name: string;
  updated_at?: string;
  updated_by?: number;
};

export default function NurseWorkForm() {
  const { register, handleSubmit, reset } = useForm();

  const onSubmit = (data: any) => {
    console.log(data);
    // ส่งข้อมูลไปยัง backend หรือเก็บไว้ใน state
  };

  return (
    <NurseFormProvider><Box sx={{ display: 'flex', justifyContent: 'center', mt: 5 }}>
      <Box sx={{ width: '100%', padding: 2, margin: 3 }}>
        <Box sx={{ mb: 3 }}>
          <Typography variant="h5" fontWeight="bold" gutterBottom>
            👤 Daily Nursing Record
          </Typography>
          <Typography variant="body1" color="text.secondary">
            กรุณากรอกข้อมูลให้ครบถ้วนก่อนกด บันทึก
          </Typography>
        </Box>
        <Box>
          <DiseaseForm />
        </Box>
      </Box>
    </Box>
    </NurseFormProvider>
  );
}
